		const stopFlags = {
			stopAfterLinkingErrors: true,
			stopAfterLexingErrors: true,
			stopAfterParsingErrors: true
		};
		if (validationOptions === true) validationOptions = stopFlags;
		else if (typeof validationOptions === "object") validationOptions = {
			...validationOptions,
			...stopFlags
		};
