/**
* Documentation provider that first tries to use triple-slash comments and falls back to JSDoc comments.
*/
var ZModelDocumentationProvider = class extends langium.JSDocDocumentationProvider {
	getDocumentation(node) {
		if ("comments" in node && Array.isArray(node.comments) && node.comments.length > 0) return node.comments.map((c) => c.replace(/^[/]*\s*/, "")).join("\n");
		return super.getDocumentation(node);
	}
};
